/* eslint-disable space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import rfftf = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});

	rfftf( x ); // $ExpectType complexndarray
	rfftf( x, {} ); // $ExpectType complexndarray
	rfftf( x, { 'n': 8 } ); // $ExpectType complexndarray
	rfftf( x, { 'normalize': 'ortho' } ); // $ExpectType complexndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	rfftf( '5' ); // $ExpectError
	rfftf( 5 ); // $ExpectError
	rfftf( true ); // $ExpectError
	rfftf( false ); // $ExpectError
	rfftf( null ); // $ExpectError
	rfftf( void 0 ); // $ExpectError
	rfftf( {} ); // $ExpectError
	rfftf( ( x: number ): number => x ); // $ExpectError

	rfftf( '5', {} ); // $ExpectError
	rfftf( 5, {} ); // $ExpectError
	rfftf( true, {} ); // $ExpectError
	rfftf( false, {} ); // $ExpectError
	rfftf( null, {} ); // $ExpectError
	rfftf( void 0, {} ); // $ExpectError
	rfftf( {}, {} ); // $ExpectError
	rfftf( ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});

	rfftf( x, '5' ); // $ExpectError
	rfftf( x, 5 ); // $ExpectError
	rfftf( x, true ); // $ExpectError
	rfftf( x, false ); // $ExpectError
	rfftf( x, null ); // $ExpectError
	rfftf( x, [] ); // $ExpectError
	rfftf( x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});

	rfftf(); // $ExpectError
	rfftf( x, {}, {} ); // $ExpectError
}

// Attached to the function is an `assign` method which returns an ndarray...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});
	const out = zeros( [ 3 ], {
		'dtype': 'complex128'
	});

	rfftf.assign( x, out ); // $ExpectType complex128ndarray
	rfftf.assign( x, out, {} ); // $ExpectType complex128ndarray
	rfftf.assign( x, out, { 'normalize': 'ortho' } ); // $ExpectType complex128ndarray
	rfftf.assign( x, out, { 'n': 8 } ); // $ExpectType complex128ndarray
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an ndarray...
{
	const out = zeros( [ 3 ], {
		'dtype': 'complex128'
	});

	rfftf.assign( '5', out ); // $ExpectError
	rfftf.assign( 5, out ); // $ExpectError
	rfftf.assign( true, out ); // $ExpectError
	rfftf.assign( false, out ); // $ExpectError
	rfftf.assign( null, out ); // $ExpectError
	rfftf.assign( void 0, out ); // $ExpectError
	rfftf.assign( {}, out ); // $ExpectError
	rfftf.assign( ( x: number ): number => x, out ); // $ExpectError

	rfftf.assign( '5', out, {} ); // $ExpectError
	rfftf.assign( 5, out, {} ); // $ExpectError
	rfftf.assign( true, out, {} ); // $ExpectError
	rfftf.assign( false, out, {} ); // $ExpectError
	rfftf.assign( null, out, {} ); // $ExpectError
	rfftf.assign( void 0, out, {} ); // $ExpectError
	rfftf.assign( {}, out, {} ); // $ExpectError
	rfftf.assign( ( x: number ): number => x, out, {} ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an output argument which is not an ndarray...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});

	rfftf.assign( x, '5' ); // $ExpectError
	rfftf.assign( x, 5 ); // $ExpectError
	rfftf.assign( x, true ); // $ExpectError
	rfftf.assign( x, false ); // $ExpectError
	rfftf.assign( x, null ); // $ExpectError
	rfftf.assign( x, void 0 ); // $ExpectError
	rfftf.assign( x, {} ); // $ExpectError
	rfftf.assign( x, ( x: number ): number => x ); // $ExpectError

	rfftf.assign( x, '5', {} ); // $ExpectError
	rfftf.assign( x, 5, {} ); // $ExpectError
	rfftf.assign( x, true, {} ); // $ExpectError
	rfftf.assign( x, false, {} ); // $ExpectError
	rfftf.assign( x, null, {} ); // $ExpectError
	rfftf.assign( x, void 0, {} ); // $ExpectError
	rfftf.assign( x, {}, {} ); // $ExpectError
	rfftf.assign( x, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an options argument which is not an object...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});
	const out = zeros( [ 3 ], {
		'dtype': 'complex128'
	});

	rfftf.assign( x, out, '5' ); // $ExpectError
	rfftf.assign( x, out, 5 ); // $ExpectError
	rfftf.assign( x, out, true ); // $ExpectError
	rfftf.assign( x, out, false ); // $ExpectError
	rfftf.assign( x, out, null ); // $ExpectError
	rfftf.assign( x, out, [] ); // $ExpectError
	rfftf.assign( x, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an unsupported number of arguments...
{
	const x = zeros( [ 4 ], {
		'dtype': 'float64'
	});
	const out = zeros( [ 3 ], {
		'dtype': 'complex128'
	});

	rfftf.assign(); // $ExpectError
	rfftf.assign( x ); // $ExpectError
	rfftf.assign( x, out, {}, {} ); // $ExpectError
}
